{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "A comparative human study reported oral bioavailability of pyridostigmine, the query molecule, as 7.6%, which is well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In fasting myasthenic patients, neostigmine—a closely related quaternary ammonium dimethylcarbamate—had absolute oral bioavailability of 2.0 ± 0.33% after oral dosing versus i.v., supporting low systemic availability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Bambuterol, a dimethylcarbamate-containing analogue, showed oral bioavailability of about 10% in healthy adults, below the 20% threshold, consistent with low F for carbamate-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Acamprosate, a polar/charged drug, had about 11% oral bioavailability under fasting conditions, illustrating that charged and poorly permeable molecules tend to have low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pyridostigmine, a quaternary ammonium carbamate. Direct human data for pyridostigmine (7.6%) and the very close analogue neostigmine (1–2% under fasting) show oral bioavailability well below 20%. Additional carbamate-containing analogues (bambuterol ~10%) and polar/charged drugs (acamprosate ~11%) support the same direction. The permanent positive charge and low passive permeability are consistent with these measurements. Therefore, predict low.",
  "evidence_gaps": [
    "No dedicated absolute bioavailability study for the exact query molecule under fasted conditions was provided, but pyridostigmine is named in C39.",
    "No evidence on active uptake transporters that could raise F above 20%.",
    "No data on food effect or formulation for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

